#!/usr/bin/env node
//
// Packages the Chrome build as a signed CRX3 file.
//
// Chrome and Chromium both expose --pack-extension, which is the same code path
// the browser uses for "Pack extension". A stable signing key is required to keep
// the extension ID unchanged between releases.
//
// Key resolution:
//   1. CHROME_EXTENSION_KEY as PEM text (CI secret) or as a path to a .pem file
//   2. build/chrome-extension.pem (local builds)
//   3. generated by Chrome on first local build and saved to build/chrome-extension.pem
//
// usage:  node scripts/pack-chrome.js
//         CHROME_BIN=/path/to/chrome CHROME_EXTENSION_KEY=... node scripts/pack-chrome.js

const { execFileSync, spawnSync } = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');
const { getBuildVersion } = require('./version-helper');

const ROOT = path.join(__dirname, '..');
const DIST = path.join(ROOT, 'dist');
const BUILD = path.join(ROOT, 'build');
const version = getBuildVersion();
const output = path.join(BUILD, `xdAnswers-chrome-${version}.crx`);
const generatedCrx = path.join(ROOT, 'dist.crx');
const generatedPem = path.join(ROOT, 'dist.pem');
const localKey = path.join(BUILD, 'chrome-extension.pem');

function findChrome() {
    const candidates = [
        process.env.CHROME_BIN,
        'google-chrome-stable',
        'google-chrome',
        'chromium',
        'chromium-browser'
    ].filter(Boolean);

    for (const candidate of candidates) {
        const result = spawnSync(candidate, ['--version'], { encoding: 'utf-8' });
        if (result.status === 0) return candidate;
    }

    throw new Error(
        'Chrome/Chromium not found. Install it or set CHROME_BIN to the browser executable.'
    );
}

function resolveKey() {
    const value = (process.env.CHROME_EXTENSION_KEY || '').trim();
    if (value) {
        if (value.includes('-----BEGIN')) {
            const keyPath = path.join(BUILD, 'chrome-extension.pem');
            fs.writeFileSync(keyPath, value.endsWith('\n') ? value : value + '\n', {
                mode: 0o600
            });
            return keyPath;
        }
        const keyPath = path.resolve(ROOT, value);
        if (!fs.existsSync(keyPath)) {
            throw new Error(`CHROME_EXTENSION_KEY file not found: ${keyPath}`);
        }
        return keyPath;
    }

    if (fs.existsSync(localKey)) return localKey;
    return null;
}

function pack() {
    if (!fs.existsSync(path.join(DIST, 'manifest.json'))) {
        throw new Error('dist/manifest.json not found. Run "node scripts/build.js chrome" first.');
    }

    fs.mkdirSync(BUILD, { recursive: true });
    fs.rmSync(generatedCrx, { force: true });
    fs.rmSync(generatedPem, { force: true });
    fs.rmSync(output, { force: true });

    const key = resolveKey();
    const profile = fs.mkdtempSync(path.join(os.tmpdir(), 'xdanswers-crx-'));
    const chrome = findChrome();
    const args = [
        '--headless',
        '--no-sandbox',
        '--disable-gpu',
        '--disable-dev-shm-usage',
        '--no-first-run',
        `--user-data-dir=${profile}`,
        `--pack-extension=${DIST}`
    ];
    if (key) args.push(`--pack-extension-key=${key}`);

    try {
        execFileSync(chrome, args, { cwd: ROOT, stdio: 'inherit' });
    } finally {
        fs.rmSync(profile, { recursive: true, force: true });
    }

    if (!fs.existsSync(generatedCrx)) {
        throw new Error('Chrome did not produce dist.crx.');
    }

    const header = fs.readFileSync(generatedCrx).subarray(0, 4).toString('ascii');
    if (header !== 'Cr24') {
        throw new Error('Chrome produced an invalid CRX file.');
    }

    fs.renameSync(generatedCrx, output);

    if (!key) {
        if (!fs.existsSync(generatedPem)) {
            throw new Error('Chrome did not produce a signing key.');
        }
        fs.renameSync(generatedPem, localKey);
        console.warn(`Generated a new Chrome signing key: ${path.relative(ROOT, localKey)}`);
        console.warn('Keep this file to preserve the extension ID between local builds.');
        console.warn('Set CHROME_EXTENSION_KEY in CI for a stable release extension ID.');
    }

    console.log(`Chrome CRX: ${path.relative(ROOT, output)}`);
}

try {
    pack();
} catch (error) {
    console.error(error.message);
    process.exit(1);
}
